309	     * applied only where referenced via {@code qualifiedByName} (and when called directly,
310	     * e.g. on update).
311	     */
312	    @Named("normalizeEmail")
313	    default String normalizeEmail(String email) {
314	        return email == null ? null : email.toLowerCase(Locale.ROOT);
315	    }
316	
317	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
318	
319	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
320	
321	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
322	        OwnerPageDto ownerPageDto = new OwnerPageDto();
323	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
324	        ownerPageDto.setPage(ownerPage.getNumber());
325	        ownerPageDto.setSize(ownerPage.getSize());
326	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
327	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
328	        return ownerPageDto;
329	    }
330	}
